<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Shipping Label {{ $order->number }}</title><style>body{font:14px Arial;max-width:600px;margin:24px auto;padding:20px;color:#111}section{border:1px solid #222;padding:16px;margin:12px 0}p{overflow-wrap:anywhere}table{width:100%;border-collapse:collapse}td,th{padding:8px;text-align:left;border-bottom:1px solid #ccc}@media print{button{display:none}body{margin:0;padding:0}section{break-inside:avoid}}</style><body><button onclick="window.print()">Print label</button><h1>Vendo · {{ $order->number }}</h1><p>Vendo tracking: {{ $order->tracking_number }}</p>@if($order->carrier_tracking_number)<p>{{ $order->carrier_name }}: {{ $order->carrier_tracking_number }}</p>@endif<section><h2>Deliver to</h2><p>{{ $order->buyer?->name }} · {{ $order->buyer?->phone_number }}</p><p>{{ $order->shipping_address }}</p></section><section><h2>Sender</h2><p>{{ $seller->sellerDetail?->business_name??$seller->name }} · {{ $seller->phone_number }}</p><p>{{ implode(', ',array_filter([$seller->sellerDetail?->house_no,$seller->sellerDetail?->street,$seller->sellerDetail?->barangay,$seller->sellerDetail?->municipality,$seller->sellerDetail?->province,$seller->sellerDetail?->zip_code])) }}</p></section><section><p>Payment: {{ strtoupper($order->payment_mode??'') }}</p><strong>Total: ₱{{ number_format($order->total_amount,2) }}</strong><p>Rider: {{ $order->courier?->name??'Awaiting assignment' }}</p><table><thead><tr><th>Item</th><th>Qty</th></tr></thead><tbody>@foreach($order->items as $item)<tr><td>{{ $item->product?->name }} {{ $item->color }} {{ $item->size }}</td><td>{{ $item->quantity }}</td></tr>@endforeach</tbody></table></section></body></html>
